const ctx = $('Shape+Accumulate: Public Records').first().json;
const raw = $input.all();
const errorItem = raw.find((i) => i.json && i.json.error);

// Google News est un AGREGATEUR, pas une source : toutes ses URL pointent vers
// news.google.com et son libelle ecrase l'editeur reel (Les Echos, Tribuca.net...).
// On retablit l'editeur, sans quoi la regle anti-bruit du scoring traite 100
// articles de 30 medias differents comme une seule source qui inonde.
function extractPublisher(entry, fallback) {
  const src = entry.source;
  const fromField = typeof src === 'string' ? src : ((src && (src.title || src.name)) || null);
  if (fromField && String(fromField).trim()) return String(fromField).trim();
  // Fallback : Google News suffixe systematiquement le titre par " - Editeur"
  // (verifie sur 100/100 items du flux reel).
  const t = entry.title || '';
  const sep = t.lastIndexOf(' - ');
  if (sep > 0) {
    const suffix = t.slice(sep + 3).trim();
    if (suffix && suffix.length <= 60) return suffix;
  }
  return fallback;
}

function stripPublisher(title, publisher) {
  if (!title || !publisher) return title;
  const suffix = ' - ' + publisher;
  return title.endsWith(suffix) ? title.slice(0, -suffix.length).trim() : title;
}

let newItems = [];
if (!errorItem && ctx.settings.includeTenders) {
  newItems = raw.filter((i) => i.json && i.json.title).map((i) => {
    const publisher = extractPublisher(i.json, 'Google News (marches publics)');
    return {
      title: stripPublisher(i.json.title, publisher),
      url: i.json.link,
      publishedAt: i.json.isoDate || i.json.pubDate || null,
      snippet: (i.json.contentSnippet || i.json.content || '').slice(0, 600),
      sourceType: 'public_tender',
      sourceName: publisher,
      collectedVia: 'Google News (marches publics)',
      collectionMethod: 'scrape',
    };
  });
}

return [{
  json: {
    ...ctx,
    collectedItems: [...ctx.collectedItems, ...newItems],
  }
}];

const ctx = $input.first().json;
const items = Array.isArray(ctx.collectedItems) ? ctx.collectedItems : [];
const existingKeys = new Set(ctx.existingDedupeKeys || []);

const MAX_AGE_DAYS = 120;
const MAX_ITEMS = 40;

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(36);
}

function normalizeTitle(t) {
  return (t || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const seenKeys = new Set();
const seenTitles = new Set();
const kept = [];

for (const it of items) {
  if (!it.url || !it.title) continue;

  // Au-dela de 120 jours, freshness() vaut deja 0 : l'item consomme du budget
  // LLM sans jamais pouvoir peser dans le score. Un item sans date est garde
  // (traite en fraicheur moyenne plus bas dans le scoring).
  if (it.publishedAt) {
    const d = new Date(it.publishedAt);
    if (!isNaN(d) && (Date.now() - d.getTime()) / 86400000 > MAX_AGE_DAYS) continue;
  }

  const dedupeKey = `${it.sourceType}:${simpleHash(it.url)}`;
  if (existingKeys.has(dedupeKey) || seenKeys.has(dedupeKey)) continue;

  // Dedup douce sur le titre normalise : un meme evenement (depeche AFP,
  // communique) est repris a l'identique par plusieurs editeurs. On garde la
  // premiere occurrence. Comparaison sur titre EXACT normalise seulement —
  // deux angles differents sur le meme fait restent deux signaux distincts.
  const titleKey = normalizeTitle(it.title);
  if (titleKey && seenTitles.has(titleKey)) continue;

  seenKeys.add(dedupeKey);
  if (titleKey) seenTitles.add(titleKey);
  kept.push({ ...it, dedupeKey });
}

// Garde-fou cout LLM (40 candidats max), reparti en TOURNIQUET entre
// collecteurs et par fraicheur decroissante. Un simple slice(0, 40) sur l'ordre
// de collecte laissait la centaine d'actualites saturer tout le budget : les
// signaux de recrutement et d'appels d'offres — les plus actionnables pour une
// ESN — n'etaient jamais qualifies.
// TOURNIQUET — cle par SOURCE EFFECTIVE, jamais par sourceType seul : avec le
// corpus sectoriel (Lot 5), jusqu'a 12 domaines distincts passent tous par
// sourceType='sector_corpus' et s'ecraseraient entre eux dans une seule file.
function roundRobinKey(it) {
  if (it.sourceCatalogId) return `id:${it.sourceCatalogId}`;
  if (it.sourceKey) return `key:${it.sourceKey}`;
  if (it.sourceName) return `name:${it.sourceName.toLowerCase().trim()}`;
  return `type:${it.sourceType}`;
}

const byKey = new Map();
for (const it of kept) {
  const key = roundRobinKey(it);
  if (!byKey.has(key)) byKey.set(key, []);
  byKey.get(key).push(it);
}
for (const group of byKey.values()) {
  group.sort((a, b) => {
    const da = a.publishedAt ? new Date(a.publishedAt).getTime() : 0;
    const db = b.publishedAt ? new Date(b.publishedAt).getTime() : 0;
    return db - da;
  });
}

const queues = Array.from(byKey.values());
const capped = [];
let progress = true;
while (capped.length < MAX_ITEMS && progress) {
  progress = false;
  for (const queue of queues) {
    if (queue.length === 0) continue;
    capped.push(queue.shift());
    progress = true;
    if (capped.length >= MAX_ITEMS) break;
  }
}

capped.forEach((it, idx) => { it.id = `item_${idx}`; });

return [{
  json: {
    runId: ctx.runId,
    workspaceId: ctx.workspaceId,
    companyId: ctx.companyId,
    callbackUrl: ctx.callbackUrl,
    company: ctx.company,
    normalizedItems: capped,
    itemsCollectedTotal: items.length,
    itemsAfterDedup: capped.length,
    sectorSourcesLoaded: ctx.sectorSourcesLoaded ?? 0,
    sectorSourcesQueried: ctx.sectorSourcesQueried ?? 0,
    sectorItemsCollected: ctx.sectorItemsCollected ?? 0,
    sectorItemsAfterDedup: ctx.sectorItemsAfterDedup ?? 0,
  }
}];

const upstream = $('Build Qualification Prompt').first().json;
const response = $input.first().json;

// Detection explicite d'une réponse tronquée par max_tokens : sinon l'échec ne
// se voit qu'indirectement via un JSON.parse cassé plus bas, avec un message
// confus (un simple extrait de texte). Ici l'erreur nomme la vraie cause.
if (response.stop_reason === 'max_tokens') {
  throw new Error(`Qualification LLM tronquée (stop_reason=max_tokens, ${(response.usage && response.usage.output_tokens) || '?'} tokens de sortie) — augmenter max_tokens sur le nœud "LLM Batch Qualification" ou réduire le plafond d'items par lot (actuellement 40, cf. Normalize & Dedup Items).`);
}

const textBlock = (response.content || []).find((b) => b.type === 'text');
const rawText = (textBlock && textBlock.text) || '';

function extractJson(text) {
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) return fenced[1].trim();
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) return text.slice(first, last + 1);
  return text;
}

function repair(text) {
  return text.replace(/[\u201c\u201d]/g, '"').replace(/[\u2018\u2019]/g, "'").replace(/,\s*([}\]])/g, '$1');
}

let parsed;
try {
  parsed = JSON.parse(repair(extractJson(rawText)));
} catch (e) {
  throw new Error('Qualification LLM : réponse non-JSON exploitable : ' + rawText.slice(0, 300));
}

const byId = new Map((upstream.normalizedItems || []).map((it) => [it.id, it]));
const TAXONOMY = new Set(['leadership_change','growth_event','it_transformation','cyber_risk','regulatory_window','public_tender','hiring_signal','market_pressure','partnership_or_vendor','weak_signal']);

const qualifiedItems = (parsed.items || []).map((q) => {
  const base = byId.get(q.id);
  if (!base) return null;
  const category = TAXONOMY.has(q.category) ? q.category : 'weak_signal';
  const clamp01 = (v) => Math.max(0, Math.min(1, typeof v === 'number' ? v : 0));
  return {
    ...base,
    category,
    pertinenceEsn: clamp01(q.pertinence_esn),
    urgence: clamp01(q.urgence),
    fitPractice: clamp01(q.fit_practice),
    confidence: clamp01(q.confidence),
    summary: q.summary || base.title,
    justification: q.justification || '',
    recommendedAction: q.recommended_action || null,
  };
}).filter(Boolean);

return [{
  json: {
    runId: upstream.runId,
    workspaceId: upstream.workspaceId,
    companyId: upstream.companyId,
    callbackUrl: upstream.callbackUrl,
    company: upstream.company,
    itemsCollectedTotal: upstream.itemsCollectedTotal,
    itemsAfterDedup: upstream.itemsAfterDedup,
    qualifiedItems,
    llmModel: response.model || 'claude-sonnet-5',
    llmTokensInput: (response.usage && response.usage.input_tokens) || null,
    llmTokensOutput: (response.usage && response.usage.output_tokens) || null,
  }
}];

const data = $input.first().json;

const RELIABILITY_BY_SOURCE_TYPE = {
  official_site: 0.75,
  news_media: 0.55,
  regulatory_filing: 0.7,
  public_tender: 0.65,
};

function freshness(publishedAt) {
  if (!publishedAt) return 0.5;
  const d = new Date(publishedAt);
  if (isNaN(d)) return 0.5;
  const ageHours = (Date.now() - d.getTime()) / 3600000;
  if (ageHours <= 48) return 1.0;
  const ageDays = ageHours / 24;
  if (ageDays >= 30) return 0.0;
  return Math.max(0, Math.min(1, 1 - (ageDays - 2) / 28));
}

// Un element hors sujet (homonymie : le "Prix Robertet" est une course
// hippique, pas le parfumeur) ressort a zero sur les TROIS axes de
// qualification. On ne l'ecrit pas en base : un signal non actionnable pollue
// le cockpit autant qu'il coute a stocker. Le compte reste trace dans le
// resume du run. Seuil volontairement tres conservateur — il faut etre nul
// PARTOUT pour etre ecarte : un signal faible mais reel sur un seul axe passe.
const MIN_SIGNAL = 0.2;
const relevantItems = data.qualifiedItems.filter(
  (it) => it.pertinenceEsn >= MIN_SIGNAL || it.fitPractice >= MIN_SIGNAL || it.urgence >= MIN_SIGNAL
);
const rejectedOffTopic = data.qualifiedItems.length - relevantItems.length;

let scored = relevantItems.map((it) => {
  const reliability = RELIABILITY_BY_SOURCE_TYPE[it.sourceType] ?? 0.5;
  const fresh = freshness(it.publishedAt);
  const globalScore = Math.round((0.35 * it.pertinenceEsn + 0.20 * fresh + 0.20 * it.urgence + 0.15 * it.fitPractice + 0.10 * reliability) * 1000) / 1000;
  const now = new Date();
  const detectedAt = now.toISOString();
  const expiresAt = new Date(now.getTime() + 60 * 24 * 3600 * 1000).toISOString();
  const status = it.confidence < 0.40 ? 'needs_review' : 'new';

  return {
    ...it,
    reliability,
    freshness: fresh,
    globalScore,
    detectedAt,
    expiresAt,
    status,
  };
});

// Règle "source trop bruyante" (§10) : si une source dépasse 20 signaux sur ce run,
// ne conserver que les 5 au score global le plus élevé pour cette source.
const bySource = new Map();
for (const it of scored) {
  const key = it.sourceName || it.sourceType;
  if (!bySource.has(key)) bySource.set(key, []);
  bySource.get(key).push(it);
}

let capped = [];
let noisySourcesCapped = false;
for (const group of bySource.values()) {
  if (group.length > 20) {
    noisySourcesCapped = true;
    group.sort((a, b) => b.globalScore - a.globalScore);
    capped.push(...group.slice(0, 5));
  } else {
    capped.push(...group);
  }
}

return [{
  json: {
    runId: data.runId,
    workspaceId: data.workspaceId,
    companyId: data.companyId,
    callbackUrl: data.callbackUrl,
    company: data.company,
    itemsCollectedTotal: data.itemsCollectedTotal,
    itemsAfterDedup: data.itemsAfterDedup,
    scoredItems: capped,
    rejectedOffTopic,
    noisySourcesCapped,
    llmModel: data.llmModel,
    llmTokensInput: data.llmTokensInput,
    llmTokensOutput: data.llmTokensOutput,
  }
}];

const data = $input.first().json;

function canonicalUrl(url) {
  try {
    const u = new URL(url);
    u.search = '';
    u.hash = '';
    return u.toString();
  } catch (e) {
    return url;
  }
}

const bySourceKey = new Map();
for (const it of data.scoredItems) {
  const sourceKey = `account_watch:${it.sourceType}:${it.dedupeKey}`;
  if (bySourceKey.has(sourceKey)) continue;
  bySourceKey.set(sourceKey, {
    workspace_id: data.workspaceId,
    source_type: it.sourceType,
    source_name: it.sourceName,
    source_url: it.url,
    canonical_url: canonicalUrl(it.url),
    published_at: it.publishedAt || null,
    source_key: sourceKey,
    evidence_excerpt: (it.snippet || it.summary || '').slice(0, 500),
    reliability_score: it.reliability,
    collection_method: it.collectionMethod,
    technical_metadata: { collector: 'intel-033-account-watch-refresh', collectedVia: it.collectedVia || null, runId: data.runId, sourceCatalogId: it.sourceCatalogId || null, corpusId: it.corpusId || null },
  });
}

const sourcesPayload = Array.from(bySourceKey.values());
const sourceKeys = Array.from(bySourceKey.keys());

return [{
  json: {
    runId: data.runId,
    workspaceId: data.workspaceId,
    companyId: data.companyId,
    callbackUrl: data.callbackUrl,
    company: data.company,
    itemsCollectedTotal: data.itemsCollectedTotal,
    itemsAfterDedup: data.itemsAfterDedup,
    scoredItems: data.scoredItems,
    sourcesPayload,
    sourceKeys,
    noisySourcesCapped: data.noisySourcesCapped,
    llmModel: data.llmModel,
    llmTokensInput: data.llmTokensInput,
    llmTokensOutput: data.llmTokensOutput,
  }
}];

const data = $('Build Sources Payload').first().json;
const resolved = $input.all().map((i) => i.json).filter((r) => r && r.source_key);
const idBySourceKey = new Map(resolved.map((r) => [r.source_key, r.id]));

const dedupeKeyToSourceKey = new Map();
for (const it of data.scoredItems) {
  dedupeKeyToSourceKey.set(it.dedupeKey, `account_watch:${it.sourceType}:${it.dedupeKey}`);
}

const signalsPayload = data.scoredItems.map((it) => {
  const sourceKey = dedupeKeyToSourceKey.get(it.dedupeKey);
  const sourceId = idBySourceKey.get(sourceKey) || null;
  return {
    workspace_id: data.workspaceId,
    company_id: data.companyId,
    signal_category: it.category,
    signal_type: `account_watch_${it.sourceType}`,
    title: it.title.slice(0, 500),
    summary: it.summary,
    event_at: it.publishedAt || null,
    detected_at: it.detectedAt,
    last_evidence_at: it.detectedAt,
    expires_at: it.expiresAt,
    dedupe_key: it.dedupeKey,
    confidence_score: it.confidence,
    relevance_score: it.pertinenceEsn,
    urgency_score: it.urgence,
    potential_value_score: it.fitPractice,
    global_score: it.globalScore,
    score_details: {
      pertinence_esn: it.pertinenceEsn,
      freshness: it.freshness,
      urgence: it.urgence,
      fit_practice: it.fitPractice,
      reliability: it.reliability,
      weights: { pertinence_esn: 0.35, freshness: 0.20, urgence: 0.20, fit_practice: 0.15, reliability: 0.10 },
    },
    score_justification: it.justification,
    recommended_action: it.recommendedAction,
    status: it.status,
    run_id: data.runId,
    primary_source_id: sourceId,
  };
});

return [{
  json: {
    runId: data.runId,
    workspaceId: data.workspaceId,
    companyId: data.companyId,
    callbackUrl: data.callbackUrl,
    company: data.company,
    itemsCollectedTotal: data.itemsCollectedTotal,
    itemsAfterDedup: data.itemsAfterDedup,
    noisySourcesCapped: data.noisySourcesCapped,
    signalsPayload,
    llmModel: data.llmModel,
    llmTokensInput: data.llmTokensInput,
    llmTokensOutput: data.llmTokensOutput,
  }
}];

// Sortie en UN SEUL item porteur du tableau : un Code node qui renvoie [] n'emet
// aucun item, et n8n n'execute pas un noeud sans item en entree — la chaine
// s'arreterait ici en silence (execution "succeeded", zero ecriture, zero callback).
const insertedSignals = $input.all().map((i) => i.json).filter((r) => r && r.id && r.primary_source_id);

const linksPayload = insertedSignals.map((s) => ({
  workspace_id: s.workspace_id,
