}));

return [{ json: { linksPayload, linksCount: linksPayload.length } }];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;
let companyId = null;
let workspaceId = null;

try {
  const vp = $('Validate Payload').item.json;
  runId = vp.runId || null;
  callbackUrl = vp.callbackUrl || null;
  companyId = vp.companyId || null;
  workspaceId = vp.workspaceId || null;
} catch (e) {
  // Validate Payload n'a produit aucune sortie exploitable (payload rejeté avant validation).
}

let errorMessage = 'Erreur inconnue dans le workflow intel-033-account-watch-refresh';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

// Si le payload a été rejeté avant la validation (signature invalide ou champ
// requis manquant, callbackUrl compris), on ne connaît aucune URL de confiance
// à notifier — inutile (et risqué) de tenter un callback vers une valeur non
// vérifiée. On s'arrête ici : l'erreur reste visible dans les Executions n8n.
if (!callbackUrl) {
  return [];
}

const callbackBody = {
  n8nExecutionId: $execution.id,
  n8nWorkflowId: $workflow.id,
  runId,
  phase: 1,
  resultType: 'account_watch_refresh',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{
  json: {
    runId,
    callbackUrl,
    companyId,
    workspaceId,
    errorMessage,
    rawBody: JSON.stringify(callbackBody),
  }
}];

// Aucun element collecte (ou tout deja connu) : on court-circuite l'appel LLM
// — zero token depense pour qualifier une liste vide — et on produit
// directement la forme de sortie attendue par "Compute Scores & Apply Rules".
const upstream = $('Filter Administrative Static Items').first().json;

return [{
  json: {
    runId: upstream.runId,
    workspaceId: upstream.workspaceId,
    companyId: upstream.companyId,
    callbackUrl: upstream.callbackUrl,
    company: upstream.company,
    itemsCollectedTotal: upstream.itemsCollectedTotal,
    itemsAfterDedup: upstream.itemsAfterDedup,
    qualifiedItems: [],
    llmModel: null,
    llmTokensInput: null,
    llmTokensOutput: null,
  }
}];

// Pivot stable de fin de run : lit "Compute Scores & Apply Rules", seul noeud
// traverse par TOUTES les branches (avec ou sans signal a ecrire). Ne jamais
// referencer ici un noeud d'ecriture Supabase sans garde : selon la branche
// empruntee il peut n'avoir jamais ete execute, et la reference leve alors.
const data = $('Compute Scores & Apply Rules').first().json;
// Lot 5 — ces compteurs existent quel que soit le chemin emprunte (LLM ou
// Skip Qualification) : on les lit directement sur le noeud du filtre
// administratif plutot que de les faire traverser toute la chaine de
// qualification (moins de noeuds a toucher, meme risque).
const adminFilterData = $('Filter Administrative Static Items').first().json;

const byCategory = {};
for (const s of data.scoredItems) {
  byCategory[s.category] = (byCategory[s.category] || 0) + 1;
}

let signalsWritten = 0;
try {
  signalsWritten = $('Supabase: Upsert Signals').all().filter((i) => i.json && i.json.id).length;
} catch (e) {
  signalsWritten = 0;
}

return [{
  json: {
    runId: data.runId,
    workspaceId: data.workspaceId,
    companyId: data.companyId,
    callbackUrl: data.callbackUrl,
    company: data.company,
    itemsCollectedTotal: data.itemsCollectedTotal,
    itemsAfterDedup: data.itemsAfterDedup,
    signalsScored: data.scoredItems.length,
    rejectedOffTopic: data.rejectedOffTopic ?? 0,
    signalsWritten,
    signalsByCategory: byCategory,
    noisySourcesCapped: data.noisySourcesCapped,
    llmModel: data.llmModel,
    llmTokensInput: data.llmTokensInput,
    llmTokensOutput: data.llmTokensOutput,
    excludedStaticCount: adminFilterData.excludedStaticCount ?? 0,
    sectorSourcesLoaded: adminFilterData.sectorSourcesLoaded ?? 0,
    sectorSourcesQueried: adminFilterData.sectorSourcesQueried ?? 0,
    sectorItemsCollected: adminFilterData.sectorItemsCollected ?? 0,
    sectorItemsAfterDedup: adminFilterData.sectorItemsAfterDedup ?? 0,
    workflowId: 'intel-033-account-watch-refresh',
    workflowVersion: '2026-08-16.1',
    definitionCommit: '<short git sha>'
  }
}];

// Instrumentation Lot 6 — calcul des métriques de collecte pour INTEL-033 (sources avec sourceCatalogId).
let sectorSources = [];
try {
  sectorSources = $('Shape Sector Sources').all().map((i) => i.json).filter((s) => s && s.sourceCatalogId && !s.placeholder);
} catch (e) {}

if (sectorSources.length === 0) {
  return [];
}

let collectedItems = [];
try {
  collectedItems = $('Shape Sector Corpus Item').all().map((i) => i.json).filter((it) => it && it.sourceCatalogId && !it.skipped);
} catch (e) {}

let errorItems = [];
try {
  errorItems = $('Ignore Sector Corpus Source Error').all().map((i) => i.json).filter((it) => it && it.sourceCatalogId && it.error);
} catch (e) {}

let dedupItems = [];
try {
  dedupItems = $('Filter Administrative Static Items').all().map((i) => i.json).filter((it) => it && it.sourceCatalogId);
} catch (e) {}

let writtenSignals = [];
try {
  writtenSignals = $('Map Signals to Sources').all().map((i) => i.json).filter((s) => s && s.primary_source_id);
} catch (e) {}

let validatePayload = {};
try {
  validatePayload = $('Validate Payload').first().json;
} catch (e) {}

const companyId = validatePayload.companyId || null;
const runId = validatePayload.runId || null;
const runKey = typeof $execution !== 'undefined' && $execution && $execution.id ? $execution.id : (runId || ('run-' + Date.now()));

const failedSourceIds = new Set(errorItems.map((it) => it.sourceCatalogId));

const collectedBySource = new Map();
for (const it of collectedItems) {
  const sId = it.sourceCatalogId;
  collectedBySource.set(sId, (collectedBySource.get(sId) || 0) + 1);
}

const dedupBySource = new Map();
for (const it of dedupItems) {
  const sId = it.sourceCatalogId;
  dedupBySource.set(sId, (dedupBySource.get(sId) || 0) + 1);
}

const retainedBySource = new Map();
for (const s of writtenSignals) {
  const sId = s.primary_source_id;
  if (!sId) continue;
  retainedBySource.set(sId, (retainedBySource.get(sId) || 0) + 1);
}

const metrics = sectorSources.map((s) => {
  const sourceCatalogId = s.sourceCatalogId;
  const corpusId = s.corpusId || null;
  const isError = failedSourceIds.has(sourceCatalogId);
  const querySucceeded = !isError;
  const itemsCollected = querySucceeded ? (collectedBySource.get(sourceCatalogId) || 0) : 0;
  const itemsAfterDedup = dedupBySource.get(sourceCatalogId) || 0;
  const itemsRetained = retainedBySource.get(sourceCatalogId) || 0;

  return {
    source_catalog_id: sourceCatalogId,
    corpus_id: corpusId,
    workflow_id: 'intel-033-account-watch-refresh',
    workflow_run_key: runKey,
    usage_scope: 'account_watch',
    company_id: companyId,
    query_succeeded: querySucceeded,
    items_collected: itemsCollected,
    items_after_dedup: itemsAfterDedup,
    items_retained: itemsRetained,
  };
});

if (metrics.length === 0) {
  return [];
}

return metrics.map((m) => ({ json: m }));

// v_effective_watch_sources est l'UNIQUE source du corpus sectoriel effectif
// (segment, sinon fallback macro, jamais les deux — encode par la vue elle-meme,
// jamais reimplemente ici). Plafond STRICT a 12 sources (§6 du prompt Lot 5) :
// la vue trie deja priority ASC, utility_score DESC (pack minimal avant enrichi,
// manual_only deja depriorise), on ne fait que reprendre cet ordre et couper.
const raw = $input.all().map((i) => i.json).filter((r) => r && !r.error && r.source_id);

const sorted = [...raw].sort((a, b) => {
  const pa = a.priority ?? 0;
  const pb = b.priority ?? 0;
  if (pa !== pb) return pa - pb;
  return (b.utility_score ?? 0) - (a.utility_score ?? 0);
});
const capped = sorted.slice(0, 12);

const sectorSourcesLoaded = raw.length;
const sectorSourcesQueried = capped.length;

// IMPORTANT : ne jamais retourner [] ici (§19/§Lot 0 : un noeud sans item de
// sortie arrete l'execution n8n entiere). 0 source corpus est un cas normal
// (§17) — on emet un placeholder qui traversera la boucle sans jamais
// declencher de requete reseau utile, et sera filtre naturellement en aval.
if (capped.length === 0) {
  return [{ json: { placeholder: true, sectorSourcesLoaded, sectorSourcesQueried: 0 } }];
}

return capped.map((r) => ({
  json: {
    sourceCatalogId: r.source_id,
    sourceKey: r.source_key,
    sourceName: r.publisher || r.source_name,
    searchDomain: r.search_domain,
    corpusId: r.corpus_id,
    sectorSourcesLoaded,
    sectorSourcesQueried,
  },
}));

// Une requete par source (jamais par variante) : plafond de 12 requetes
// reseau au total pour le corpus sectoriel (§7 du prompt). Les alias de
// compte (query_aliases / nameVariants deja resolus par Build Targeted
// Queries) sont combines en OR DANS la meme requete, pas en requetes
// separees.
const s = $json;
if (s.placeholder) {
  return { json: { ...s, feedUrl: null } };
}

const ctx = $('Shape+Accumulate: Tenders').first().json;
const names = (ctx.nameVariants || []).slice(0, 2).map((n) => '"' + n + '"').join(' OR ');
const query = names ? `site:${s.searchDomain} (${names})` : `site:${s.searchDomain}`;
const feedUrl = `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=fr&gl=FR&ceid=FR:fr`;

return { json: { ...s, feedUrl } };

// Boucle a 1 source en cours (Loop Over Sector Sources, batch=1) : $json est
// l'article RSS courant, la reference nommee au noeud de boucle resout sans
// ambiguite la SEULE source en cours de traitement — meme mecanisme deja
// eprouve par veille-hebdomadaire-kredo.json (Enrichir avec Metadonnees Source).
const source = $('Loop Over Sector Sources').item.json;
const item = $json;

function extractPublisher(entry, fallback) {
  const src = entry.source;
  const fromField = typeof src === 'string' ? src : ((src && (src.title || src.name)) || null);
  if (fromField && String(fromField).trim()) return String(fromField).trim();
  const t = entry.title || '';
  const sep = t.lastIndexOf(' - ');
  if (sep > 0) {
    const suffix = t.slice(sep + 3).trim();
    if (suffix && suffix.length <= 60) return suffix;
  }
  return fallback;
}

function stripPublisher(title, publisher) {
  if (!title || !publisher) return title;
  const suffix = ' - ' + publisher;
  return title.endsWith(suffix) ? title.slice(0, -suffix.length).trim() : title;
}

if (source.placeholder || !item.title || !item.link) {
  return { json: { skipped: true, sourceCatalogId: source.sourceCatalogId || null, sourceKey: source.sourceKey || null } };
}

const publisher = extractPublisher(item, source.sourceName);

return {
  json: {
    title: stripPublisher(item.title, publisher),
    url: item.link,
    publishedAt: item.isoDate || item.pubDate || null,
    snippet: (item.contentSnippet || item.content || '').slice(0, 600),
    sourceType: 'sector_corpus',
    sourceName: publisher,
    sourceCatalogId: source.sourceCatalogId,
    corpusId: source.corpusId,
    sourceKey: source.sourceKey,
    searchDomain: source.searchDomain,
    collectedVia: 'sector_corpus',
    collectionMethod: 'scrape',
  },
};

// Une source corpus en erreur (flux inaccessible, domaine mal indexe par
// Google News) ne stoppe jamais la boucle sur les autres sources — meme regle
// que §19/§27 du prompt Lot 5 et que le collecteur historique News Media.
const source = $('Loop Over Sector Sources').item.json;
const first = $input.first().json;
const err = (first && first.error) || first;

console.log(
  `[INTEL-033] Source corpus en erreur, ignoree : ${source.sourceName || 'source inconnue'} (${source.searchDomain || 'domaine inconnu'}) — ${JSON.stringify(err).slice(0, 300)}`
);

return [{ json: { skipped: true, sourceCatalogId: source.sourceCatalogId || null, sourceKey: source.sourceKey || null } }];

const ctx = $('Shape+Accumulate: Tenders').first().json;
const shapeMeta = $('Shape Sector Sources').first().json;
const raw = $input.all().map((i) => i.json);

const collected = raw.filter((it) => it.url && it.title && !it.skipped);

function normalizeTitle(t) {
  return (t || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const seenUrls = new Set();
const seenTitles = new Set();
const deduped = [];
for (const it of collected) {
  if (seenUrls.has(it.url)) continue;
  const titleKey = normalizeTitle(it.title);
  if (titleKey && seenTitles.has(titleKey)) continue;
  seenUrls.add(it.url);
  if (titleKey) seenTitles.add(titleKey);
  deduped.push(it);
}

return [{
  json: {
    ...ctx,
    sectorItems: deduped,
    sectorSourcesLoaded: shapeMeta.sectorSourcesLoaded ?? 0,
    sectorSourcesQueried: shapeMeta.sectorSourcesQueried ?? 0,
    sectorItemsCollected: collected.length,
    sectorItemsAfterDedup: deduped.length,
  }
}];

// includeSectorCorpus === false : condition verifiee AVANT toute requete
// reseau (§18 du prompt Lot 5) — aucun cout reseau corpus, collecteurs
// historiques inchanges.
const ctx = $input.first().json;
return [{
  json: {
    ...ctx,
    sectorItems: [],
    sectorSourcesLoaded: 0,
    sectorSourcesQueried: 0,
    sectorItemsCollected: 0,
    sectorItemsAfterDedup: 0,
  }
}];

// Point de convergence unique avant Normalize & Dedup Items — les sources
// corpus doivent converger AVANT la qualification (§1 du prompt), jamais une
// deuxieme pipeline parallele jusqu'a la DB.
const data = $input.first().json;
const sectorCollected = (data.sectorItems || []).map((it) => ({ ...it, sourceType: it.sourceType || 'sector_corpus' }));

return [{
  json: {
    ...data,
    collectedItems: [...(data.collectedItems || []), ...sectorCollected],
  }
}];

// Filtre administratif deterministe (§12-15 du prompt Lot 5) — exclut AVANT
// depense LLM une information qui ne porte QUE du contenu administratif
// statique (SIREN/SIRET/NAF/siege/capital social/forme juridique) sans aucun
// verbe ou motif evenementiel detectable. La presence de vocabulaire
// administratif ne suffit JAMAIS a exclure a elle seule : un evenement
// (transfert de siege, nomination, fusion, acquisition, cession, liquidation,
// radiation, redressement, capital, creation/fermeture d'etablissement,
// attribution de marche, nouveau contrat/partenariat...) prime toujours.
// Favorise les faux negatifs : en cas de doute, on conserve.
function isAdministrativeStaticItem(item) {
  const raw = `${item.title || ''} ${item.snippet || ''}`.toLowerCase();
  const text = raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  const ADMINISTRATIVE_VOCAB = [
    'siren', 'siret', 'code naf', 'code ape', 'siege social', 'adresse du siege',
    'capital social', 'forme juridique', 'coordonnees administratives',
    'numero de tva', 'identifiant unique',
  ];
  const hasAdministrativeVocab = ADMINISTRATIVE_VOCAB.some((term) => text.includes(term));
  if (!hasAdministrativeVocab) return false;

  const EVENT_VOCAB = [
    'transfert', 'changement de dirigeant', 'nomination', 'depart', 'demission',
    'fusion', 'acquisition', 'cession', 'liquidation', 'radiation', 'redressement',
    'augmentation de capital', 'reduction de capital',
    "creation d'etablissement", 'creation d etablissement',
    "fermeture d'etablissement", 'fermeture d etablissement',
    'ouverture', 'attribution de marche', "appel d'offres", 'appel d offres',
    'nouveau contrat', 'nouveau partenariat', 'remporte', 'marche public',
  ];
  const hasEventVocab = EVENT_VOCAB.some((term) => text.includes(term));

  return !hasEventVocab;
}

const data = $input.first().json;
const before = data.normalizedItems || [];
const filtered = before.filter((it) => !isAdministrativeStaticItem(it));
const excludedStaticCount = before.length - filtered.length;

return [{
  json: {
    ...data,
    normalizedItems: filtered,
    excludedStaticCount,
  }
}];
